import{_ as i,l as n,o as a,c as l,v as o,p as s,x as t,d as c,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"向量化执行","description":"","frontmatter":{"title":"向量化执行","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/vectorized-execution.md","filePath":"cs/vectorized-execution.md","lastUpdated":1789023840000}'),E={name:"cs/vectorized-execution.md"};function h(_,e,u,A,B,m){const r=n("Mermaid");return a(),l("div",null,[e[1]||(e[1]=o('<h1 id="向量化执行" tabindex="-1">向量化执行 <a class="header-anchor" href="#向量化执行" aria-label="Permalink to &quot;向量化执行&quot;">​</a></h1><div class="epigraph"><p>一次 next 吐一批行，表达式在列向量上走紧循环；解释器税摊到数千元组上，SIMD 才有机会。</p><footer>—— 据 Boncz, Zukowski and Nes, MonetDB/X100；Abadi et al. 列存执行；Graefe Volcano 对照</footer></div><p><a href="/cs/volcano-iterator">上一课</a>钉了逐行拉模型。本课不重写 open/close。缺口是 CPU：OLAP 扫描上每行虚调用、分支、解释表达式占满流水线。向量化（vectorized execution）保持迭代器接口，把粒度改成向量（几百到几千行），算子内用列式循环。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>行存储上也可以向量化：先解一批行到列缓冲，再算谓词，再按选择向量收行。列存更自然：磁盘上已是列，扫描直接填向量。缺口是<strong>控制流仍在 Volcano 树</strong>，数据布局变成批，不是换一种查询语言。</p><p>选择向量（selection vector）：谓词结果是索引数组，避免把过滤做成物理压缩每一列。哈希探测、聚集在批上做，缓存更友好。</p><p><span class="marginnote">MonetDB/X100（VectorWise）把向量化做进商业引擎。列存与 PAX 在存储进阶课展开；本课执行侧先吃到批处理红利，即使底下仍是行页。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>next</code> 返回批或空。表达式编译成针对类型的循环（或解释但按批）。NULL 用位图，避免每值分支。对齐：批大小与缓存行、页大小的关系是调参，本课不规定 2048。</p><p>与编译执行下一课的差别：向量化仍是解释树+紧循环；编译把树打成机器码，连算子边界都可熔掉。两者可叠：编译生成的循环仍按批。</p>',10)),(a(),s(p,null,{default:t(()=>[d(r,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20NXT%5B%22next%20%E4%B8%80%E6%89%B9%22%5D%20--%3E%20COL%5B%22%E5%88%97%E5%90%91%E9%87%8F%22%5D%0A%20%20COL%20--%3E%20EXPR%5B%22%E7%B4%A7%E5%BE%AA%E7%8E%AF%E8%A1%A8%E8%BE%BE%E5%BC%8F%22%5D%0A%20%20EXPR%20--%3E%20SV%5B%22%E9%80%89%E6%8B%A9%E5%90%91%E9%87%8F%22%5D%0A%20%20SV%20--%3E%20CHILD%5B%22%E6%8B%89%E5%AD%90%E7%AE%97%E5%AD%90%E4%B8%8B%E4%B8%80%E6%89%B9%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>阻塞算子：排序仍要看见全部（或外排），但输入输出按批。自适应重优化的监测点按批计数更便宜。代价模型 CPU 项必须按批重校准，否则优化器仍以为扫描极贵。</p><p>倾斜：一批里命中率变化，向量循环仍比逐行好。极窄批（每次一行）退回 Volcano 税——OLTP 点查不一定开向量化。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲 LLVM 生成整查询。也不把 GPU 执行当主干。延迟物化决定批里有哪些列，后课再写。</p><p>后课默认：OLAP 计划按批执行；OLTP 短路径可逐行。编译执行把算子树再压成代码。</p><p>向量化消灭的是解释器，不是 I/O。I/O 仍由扫描与缓冲池决定。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>批粒度保留 Volcano 组装，摊掉每行调用。</li><li>选择向量与 NULL 位图服务紧循环。</li><li>编译执行下一课：把树变成机器码。</li><li>出处：Boncz, Zukowski, Nes；列存执行文献；Graefe。</li></ul>',9))])}const x=i(E,[["render",h]]);export{P as __pageData,x as default};
